source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    paths = []
    seeds = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]
    for r, c, color in seeds:
        points = [(r, c)]
        if color == 1:
            points.extend([(r, c + 1), (r, c + 2), (r - 1, c + 2)])
        elif color == 2:
            points.extend((r, c - k) for k in range(1, 5))
        elif color == 3:
            points.extend((r + k, c) for k in range(1, 4))
        elif color == 6:
            points.extend((r - k, c) for k in range(1, 7))
        else:
            continue
        valid = [(rr, cc) for rr, cc in points if 0 <= rr < h and 0 <= cc < w]
        paths.append((color, valid, (valid[-1] if len(valid) == len(points) else None)))
    counts = {}
    for color, points, endpoint in paths:
        for p in points:
            counts[p] = counts.get(p, 0) + 1
    collisions = [p for p, n in counts.items() if n > 1]
    # Draw each path, keeping its two colored ends and marking its trail with 5.
    for color, points, endpoint in paths:
        start = points[0]
        for p in points:
            if p == start or p == endpoint:
                out[p[0]][p[1]] = color
            else:
                out[p[0]][p[1]] = 5
    # Intersections of trails are marked 4 and send a diagonal ray down-left.
    for r, c in collisions:
        out[r][c] = 4
        rr, cc = r + 1, c - 1
        while rr < h and cc >= 0:
            out[rr][cc] = 4
            rr += 1
            cc -= 1
    return out
'''
